/**
 * The console's static console-control@1 inventory (framework/spec/CONSOLE-CONTROL.md): every view, nav entry and tab
 * row the console has, with addresses, labels and keywords, known before anything renders. Generated by
 * scripts/control-inventory.mjs into inventory.json (the server reads the same file: server/console_control.py).
 *
 * The live registry (axf/react/controlTargets) only knows what is rendered; this file fills the gap: search finds a
 * screen or tab that is not open, and the executor opens its view first when an address names something not rendered yet.
 */
import type { ControlTarget } from '../axf/core/engines/console-control';
import data from './inventory.json';

export interface InventoryView { address: string; id: string; label: string; icon?: string; keywords: string[]; source: 'shell' | 'framework' | 'plugin'; plugin?: string; nav?: string }
export interface InventoryTab { address?: string; value: string; label: string }
export interface InventoryTabGroup { address?: string; id: string | null; dynamic: boolean; view: string | null; plugin: string | null; file: string; line: number; tabs: InventoryTab[] }
export interface InventoryNav { address: string | null; id: string; label: string; section: string; icon?: string }
export interface ConsoleInventory {
  $axf: 'console-control-inventory@1';
  counts: Record<string, number>;
  views: InventoryView[];
  nav: InventoryNav[];
  tabGroups: InventoryTabGroup[];
  settings?: unknown[];
  functions?: unknown[];
  plugins?: unknown[];
}

export const inventory = data as unknown as ConsoleInventory;

const viewLabel = new Map(inventory.views.map((v) => [v.id, v.label]));

/** The label of a view id (static), else the id. */
export const inventoryViewLabel = (id: string): string => viewLabel.get(id) ?? id;

/** Views, tab rows and tabs as (virtual) targets: what search lists before they render. */
export function inventoryTargets(): ControlTarget[] {
  const out: ControlTarget[] = [];
  for (const v of inventory.views) out.push({ address: v.address, kind: 'view', label: v.label, detail: v.nav ? `Page · ${v.nav}` : 'Page', ...(v.icon ? { icon: v.icon } : {}), keywords: v.keywords, virtual: true });
  for (const g of inventory.tabGroups) {
    if (!g.address) continue;
    const where = g.view ? inventoryViewLabel(g.view) : 'Console';
    for (const t of g.tabs) if (t.address) out.push({ address: t.address, kind: 'tab', label: t.label, detail: `Tab · ${where}`, keywords: [t.value, where], parent: g.address, virtual: true });
  }
  return out;
}

/** The view a static address lives in (its leading `view:` segment), else null. */
export function inventoryViewOf(address: string): string | null {
  const m = /^view:([^/]+)/.exec(address);
  if (m) return decodeURIComponent(m[1]!);
  const g = inventory.tabGroups.find((x) => x.address && (address === x.address || address.startsWith(`${x.address}=`) || address.startsWith(`${x.address}/`)));
  return g?.view ?? null;
}
